// Host tests + listening renders. See run.sh.
#include <atomic>
#include <cassert>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <new>
#include <string>
#include <thread>
#include <vector>
#include "gx_fx.h"
static std::atomic<bool> trap{false}; static std::atomic<int> trapped{0};
#if !defined(__SANITIZE_THREAD__) && !__has_feature(thread_sanitizer)
void* operator new(size_t n){if(trap)trapped++;void*p=malloc(n);if(!p)abort();return p;}
void operator delete(void*p)noexcept{if(trap)trapped++;free(p);}
void operator delete(void*p,size_t)noexcept{if(trap)trapped++;free(p);}
#endif
using V=std::vector<float>; static int fails=0;
#define CHECK(c,...) do{ if(!(c)){fails++;printf("FAIL %s:%d ",__func__,__LINE__);printf(__VA_ARGS__);puts("");} }while(0)
static V voice(int rate,double sec){int n=rate*sec;V x(n);double ph=0;for(int i=0;i<n;i++){double t=double(i)/rate;double f0=140+30*sin(t*2.1);ph+=2*M_PI*f0/rate;double s=0;for(int h=1;h<=16&&h*f0<rate/2.2;h++)s+=sin(ph*h)/h;double e=sin(t*M_PI*3)>-.2?.25:0.;x[i]=s*e;}return x;}
static V sine(int rate,double sec,double f){V x(rate*sec);for(size_t i=0;i<x.size();i++)x[i]=.4*sin(2*M_PI*f*i/rate);return x;}
static V rd(const char*f){FILE*h=fopen(f,"rb");if(!h)return{};fseek(h,0,2);long l=ftell(h);fseek(h,0,0);std::vector<char> b(l);fread(b.data(),1,l,h);fclose(h);long p=12;while(p+8<l){uint32_t z;memcpy(&z,&b[p+4],4);if(!memcmp(&b[p],"data",4)){V x(z/4);memcpy(x.data(),&b[p+8],x.size()*4);return x;}p+=8+z+(z&1);}return{};}
static void wr(std::string f,const V&x,int sr){FILE*h=fopen(f.c_str(),"wb");uint32_t d=x.size()*4,v;uint16_t q;fwrite("RIFF",1,4,h);v=36+d;fwrite(&v,4,1,h);fwrite("WAVEfmt ",1,8,h);v=16;fwrite(&v,4,1,h);q=3;fwrite(&q,2,1,h);q=1;fwrite(&q,2,1,h);v=sr;fwrite(&v,4,1,h);v=sr*4;fwrite(&v,4,1,h);q=4;fwrite(&q,2,1,h);q=32;fwrite(&q,2,1,h);fwrite("data",1,4,h);fwrite(&d,4,1,h);fwrite(x.data(),4,x.size(),h);fclose(h);}
static V feed(gx_fx*fx,V x,int rate,int block,int*code2=nullptr){for(size_t k=0;k+block<=x.size();k+=block){int r=gx_fx_process(fx,&x[k],block,rate);if(r==GX_FX_NEED_REBUILD){if(code2)++*code2;gx_fx_rebuild(fx);}}return x;}
static double rms(const V&x,size_t a,size_t b){double s=0;b=std::min(b,x.size());for(size_t i=a;i<b;i++)s+=x[i]*x[i];return sqrt(s/std::max<size_t>(1,b-a));}
static double freq(const V&o,int rate,double a,double b){size_t s=rate*a,e=std::min(o.size(),(size_t)(rate*b));double f=-1,l=-1;int n=0;for(size_t i=s;i+1<e;i++)if(o[i]<=0&&o[i+1]>0){double t=i+o[i]/(o[i]-o[i+1]);if(f<0)f=t;l=t;n++;}return n<2?0:(n-1)*rate/(l-f);}
static double diff(const V&a,const V&b){double s=0;size_t n=std::min(a.size(),b.size());for(size_t i=0;i<n;i++)s+=(a[i]-b[i])*(a[i]-b[i]);return sqrt(s/n);}
static gx_fx* make(int p,int rate){gx_fx*fx=gx_fx_create();float z[9600]={0};int n=rate/100;gx_fx_set_preset(fx,GX_FX_NONE);gx_fx_process(fx,z,n,rate);/*teach rate*/return fx;}
static gx_fx* ready(int p,int rate){gx_fx*fx=gx_fx_create();gx_fx_set_preset(fx,p);int n=rate/100;std::vector<float> z(n,0.f);for(int i=0;i<4;i++){int r=gx_fx_process(fx,z.data(),n,rate);if(r==GX_FX_NEED_REBUILD)gx_fx_rebuild(fx);}return fx;}
void t_passthrough_exact(){gx_fx*fx=gx_fx_create();V x=voice(48000,1),y=feed(fx,x,48000,480);CHECK(!memcmp(x.data(),y.data(),x.size()*4),"not bit exact");gx_fx_destroy(fx);}
void t_none_after_effect(){gx_fx*fx=ready(GX_FX_ROBOT,48000);gx_fx_set_preset(fx,GX_FX_NONE);float z[480]={0};gx_fx_process(fx,z,480,48000);gx_fx_process(fx,z,480,48000);V x=voice(48000,1),y=feed(fx,x,48000,480);CHECK(!memcmp(x.data(),y.data(),x.size()*4),"not exact after none");gx_fx_status s;gx_fx_get_status(fx,&s);CHECK(s.active==GX_FX_NONE&&s.latency_ms==0,"status");gx_fx_destroy(fx);}
void t_noalloc(){for(int p=1;p<GX_FX_PRESET_COUNT;p++){gx_fx*fx=ready(p,48000);V x=voice(48000,3);trapped=0;trap=true;for(size_t k=0;k+480<=x.size();k+=480)gx_fx_process(fx,&x[k],480,48000);trap=false;CHECK(trapped==0,"preset %d allocs %d",p,trapped.load());gx_fx_destroy(fx);}}
void t_rates(){int rates[]={8000,16000,24000,32000,44100,48000};for(int r:rates)for(int p=1;p<GX_FX_PRESET_COUNT;p++){gx_fx*fx=gx_fx_create();gx_fx_set_preset(fx,p);int c=0;V x=voice(r,2),y=feed(fx,x,r,r/100,&c);double e=rms(y,r/2,r*2-r/10);CHECK(c==(r==48000?0:1),"rate %d preset %d rebuilds %d",r,p,c);CHECK(e>0.01,"rate %d preset %d silent rms %.4f",r,p,e);bool ok=true;for(float v:y)if(!std::isfinite(v)||fabs(v)>1.0001f)ok=false;CHECK(ok,"rate %d preset %d range",r,p);gx_fx_status s;gx_fx_get_status(fx,&s);CHECK(s.active==p&&s.rate==r,"rate %d preset %d status active=%d rate=%d",r,p,s.active,s.rate);gx_fx_destroy(fx);}}
void t_rate_change_mid(){gx_fx*fx=ready(GX_FX_GIRL,48000);int c=0;V a=voice(16000,1);a=feed(fx,a,16000,160,&c);V b=voice(48000,1);b=feed(fx,b,48000,480,&c);CHECK(c==2,"rebuild calls %d",c);gx_fx_status s;gx_fx_get_status(fx,&s);CHECK(s.rate==48000&&s.active==GX_FX_GIRL,"status");gx_fx_destroy(fx);}
void t_pitch(){struct{int p;double st;}c[]={{GX_FX_GIRL,5}};for(auto k:c){gx_fx*fx=ready(k.p,48000);V y=feed(fx,sine(48000,3,220),48000,480);double f=freq(y,48000,1,2.8),want=220*pow(2,k.st/12),ce=1200*log2(f/want);CHECK(fabs(ce)<30,"preset %d got %.1f want %.1f cents %.1f",k.p,f,want,ce);printf("  pitch preset %d: %.1f Hz, want %.1f, %.1f cents\n",k.p,f,want,ce);gx_fx_destroy(fx);}}
void t_scale_snap(){struct{int p;double in,want;}c[]={{GX_FX_AUTOTUNE_MAJOR_C,230,220},{GX_FX_AUTOTUNE_MINOR_A,230,220},{GX_FX_AUTOTUNE_HARMONIC_MINOR,410,415.3},{GX_FX_AUTOTUNE_MAJOR_C,410,392}};for(auto k:c){gx_fx*fx=ready(k.p,48000);trap=false;V y=feed(fx,sine(48000,3,k.in),48000,480);double f=freq(y,48000,1,2.8),ce=1200*log2(f/k.want);printf("  snap preset %d in %.0f: got %.1f want %.1f (%.1f cents)\n",k.p,k.in,f,k.want,ce);CHECK(fabs(ce)<35,"preset %d in %.0f got %.1f want %.1f",k.p,k.in,f,k.want);gx_fx_destroy(fx);}}
void t_all_distinct(){V x=voice(48000,3);std::vector<V> o;for(int p=1;p<GX_FX_PRESET_COUNT;p++){gx_fx*fx=ready(p,48000);o.push_back(feed(fx,x,48000,480));gx_fx_destroy(fx);}for(int a=0;a<(int)o.size();a++){CHECK(diff(x,o[a])>0.002,"preset %d equals the dry voice",a+1);for(int b=a+1;b<(int)o.size();b++){if(a+1>=GX_FX_AUTOTUNE_MAJOR_C&&b+1>=GX_FX_AUTOTUNE_MAJOR_C)continue;/*scales differ only on notes this voice never reaches; t_scale_snap covers them*/CHECK(diff(o[a],o[b])>0.001,"presets %d and %d are the same",a+1,b+1);}}}
void t_transformer_lower(){gx_fx*fx=ready(GX_FX_TRANSFORMER,48000);V x=voice(48000,3),y=feed(fx,x,48000,480);CHECK(diff(x,y)>0.02,"same");gx_fx_destroy(fx);}
void t_hall_tail(){gx_fx*fx=ready(GX_FX_HALL,48000);V x=voice(48000,1);x.resize(48000*5,0.f);std::fill(x.begin()+48000/2,x.end(),0.f);V y=feed(fx,x,48000,480);double at=rms(y,48000/2+4800,48000/2+14400),one=rms(y,48000*3/2,48000*3/2+9600),four=rms(y,48000*4,48000*4+9600);printf("  hall tail rms: 0.1s %.5f, 1s %.5f, 3.5s %.6f\n",at,one,four);CHECK(one>at*0.02,"tail too short");CHECK(four<at*0.05,"tail never decays");gx_fx_destroy(fx);}
void t_studio_room_shorter(){auto tail=[](int p){gx_fx*fx=ready(p,48000);V x=voice(48000,1);x.resize(48000*3,0.f);std::fill(x.begin()+24000,x.end(),0.f);V y=feed(fx,x,48000,480);double r=rms(y,48000,48000+9600);gx_fx_destroy(fx);return r;};CHECK(tail(GX_FX_STUDIO)<tail(GX_FX_HALL)*.5,"studio not shorter");}
void t_robot_changes(){gx_fx*fx=ready(GX_FX_ROBOT,48000);V x=voice(48000,2),y=feed(fx,x,48000,480);CHECK(diff(x,y)>0.02,"robot equals input");gx_fx_status s;gx_fx_get_status(fx,&s);CHECK(s.latency_ms==0,"robot latency %d",s.latency_ms);gx_fx_destroy(fx);}
void t_latency(){for(int p:{GX_FX_GIRL,GX_FX_TRANSFORMER}){gx_fx_status s;gx_fx*fx=ready(p,48000);gx_fx_get_status(fx,&s);CHECK(s.latency_ms>=30&&s.latency_ms<=45,"preset %d latency %d",p,s.latency_ms);printf("  latency preset %d: %d ms\n",p,s.latency_ms);gx_fx_destroy(fx);}}
void t_bypass_dry(){gx_fx*fx=ready(GX_FX_ROBOT,48000);gx_fx_set_bypass(fx,1);float z[480]={0};gx_fx_process(fx,z,480,48000);V x=voice(48000,1),y=feed(fx,x,48000,480);CHECK(diff(x,y)<1e-5,"bypass not dry %.6f",diff(x,y));gx_fx_set_bypass(fx,0);V y2=feed(fx,x,48000,480);CHECK(diff(x,y2)>0.02,"no effect after bypass");gx_fx_status s;gx_fx_get_status(fx,&s);CHECK(s.bypass==0,"status");gx_fx_destroy(fx);}
void t_watchdog(){gx_fx*fx=ready(GX_FX_HALL,48000);gx_fx_set_watchdog(fx,1,-0+3);V x=voice(48000,1);/* a 1us budget must trip */int w=0;std::vector<float> b(480);for(size_t k=0;k+480<=x.size();k+=480){memcpy(b.data(),&x[k],1920);int r=gx_fx_process(fx,b.data(),480,48000);if(r==GX_FX_WATCHDOG)w++;if(w&&r!=GX_FX_WATCHDOG&&memcmp(b.data(),&x[k],1920))CHECK(false,"not passthrough after trip");}CHECK(w==1,"trips %d",w);gx_fx_status s;gx_fx_get_status(fx,&s);CHECK(s.watchdog==1,"status");gx_fx_set_watchdog(fx,0,0);gx_fx_set_preset(fx,GX_FX_ROBOT);gx_fx_get_status(fx,&s);CHECK(s.watchdog==0,"not cleared");gx_fx_destroy(fx);}
void t_bad_input(){gx_fx*fx=ready(GX_FX_HALL,48000);float z[10]={1};CHECK(gx_fx_process(fx,z,0,48000)==1,"n=0");CHECK(gx_fx_process(fx,nullptr,480,48000)==1,"null");CHECK(gx_fx_process(fx,z,5000,48000)==1,"big");CHECK(gx_fx_set_preset(fx,99)==-1,"bad preset");CHECK(gx_fx_set_preset(fx,-1)==-1,"neg");gx_fx_destroy(fx);}
void t_nan_input(){for(int p=1;p<GX_FX_PRESET_COUNT;p++){gx_fx*fx=ready(p,48000);V x=voice(48000,1);x[12000]=NAN;x[12500]=INFINITY;V y=feed(fx,x,48000,480);V y2=feed(fx,voice(48000,1),48000,480);bool ok=true;for(float v:y2)if(!std::isfinite(v))ok=false;CHECK(ok,"preset %d not finite after NaN input",p);gx_fx_destroy(fx);}}
void t_stress(){gx_fx*fx=gx_fx_create();std::atomic<bool> stop{false};std::thread a([&]{std::vector<float> b(480);V v=voice(48000,1);size_t k=0;while(!stop){memcpy(b.data(),&v[k],1920);k=(k+480)%47520;int r=gx_fx_process(fx,b.data(),480,k%9600==0?16000:48000);(void)r;}});for(int i=0;i<3000;i++){gx_fx_set_preset(fx,i%GX_FX_PRESET_COUNT);gx_fx_rebuild(fx);gx_fx_set_bypass(fx,i&1);gx_fx_status s;gx_fx_get_status(fx,&s);}stop=true;a.join();gx_fx_destroy(fx);}
void t_int16_scale(){V x=voice(48000,3);for(int p=1;p<GX_FX_PRESET_COUNT;p++){gx_fx*f=gx_fx_create();gx_fx_set_preset(f,p);double in=0,out=0;long cnt=0;for(size_t k=0;k+480<=x.size();k+=480){float b[480];for(int i=0;i<480;i++)b[i]=x[k+i]*32768.f;double e=0;for(int i=0;i<480;i++)e+=b[i]*b[i];int rc=gx_fx_process_int16_scale(f,b,480,48000);if(rc==GX_FX_NEED_REBUILD)gx_fx_rebuild(f);if(k>48000){in+=e;for(int i=0;i<480;i++)out+=b[i]*b[i];cnt++;}}gx_fx_destroy(f);double r=std::sqrt(out/(in+1e-9));if(r<0.1){printf("  int16 scale preset %d: output/input level %.5f\n",p,r);}CHECK(r>=0.1,"int16-scale voice must stay audible");}gx_fx*f=gx_fx_create();float b[480],c[480];for(int i=0;i<480;i++)c[i]=b[i]=(float)(i*37%65536-32768);gx_fx_process_int16_scale(f,b,480,48000);CHECK(!memcmp(b,c,sizeof b),"no effect: int16-scale block unchanged");gx_fx_destroy(f);}
int main(int c,char**v){
 if(c>2&&!strcmp(v[1],"render")){V x=rd(v[2]);if(x.empty())return 2;const char*n[]={"none","studio","hall","robot","girl","transformer","boy","child","woman","man","foreigner","ethereal","magnetic","fresh","energetic","rich","muffled","round","falsetto","full","clear","resonant","loudClear","softRoom","largeRoom","valley","basement","ktv","enhancedKtv","popular","rock","vocalConcert","gramophone","autotuneMajorC","autotuneMinorA","autotuneHarmonicMinor"};for(int p=1;p<GX_FX_PRESET_COUNT;p++){gx_fx*fx=ready(p,48000);V y=feed(fx,x,48000,480);wr(std::string(v[3])+"/"+n[p]+".wav",y,48000);gx_fx_destroy(fx);}return 0;}
 if(c>1&&!strcmp(v[1],"stress")){t_stress();puts("stress done");return 0;}
 t_int16_scale();t_passthrough_exact();t_none_after_effect();t_noalloc();t_rates();t_rate_change_mid();t_pitch();t_scale_snap();t_all_distinct();t_transformer_lower();t_hall_tail();t_studio_room_shorter();t_robot_changes();t_latency();t_bypass_dry();t_watchdog();t_bad_input();t_nan_input();t_stress();
 for(int p=1;p<GX_FX_PRESET_COUNT;p++){gx_fx_bench b;int r=gx_fx_benchmark(p,48000,5,&b);CHECK(r==0,"bench");printf("  bench preset %d: p50 %d us p95 %d us max %d us latency %d ms\n",p,b.p50_us,b.p95_us,b.max_us,b.latency_ms);}
 printf(fails?"%d FAILED\n":"ALL PASS\n",fails);return fails?1:0;}
